tool_calls.arguments:
{"command":"cd /workspace && cat > check.sh <<'EOF'
#!/bin/bash
set -x
for p in $(kubectl get pods -n policy); do echo "== $p"; kubectl exec -n policy $p -- bash -c 'command -v wget; command -v curl; command -v nc; ls /dev/tcp 2>&1'; done
EOF
chmod +x check.sh && ./check.sh 2>&1 | grep -v "^+"; head -50"}

